package com.example.splitstory;
import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.cert.X509Certificate;import java.util.*;import java.util.zip.*;import com.android.apksig.ApkSigner;
/** Android-compatible packaging; desktop verification uses the exact same class. */
public final class ApkExportEngine {
public static final String TEMPLATE_PACKAGE="com.eventvn.play.template";
/** Background layer of the shell's adaptive icon; the game's 432px picture replaces it. */
static final String ICON_ART="res/drawable-nodpi-v4/icon_art.png";
static final Set<String> JS=new HashSet<>(Arrays.asList("app.js","core.js","themes.js","themes.css","style.css","vault.js","saves.js","depot.js","history.js","audio.js","sound-editor.js","feedback.js","player-bootstrap.js","game-title.js","image-compose.js","game-management.js","creator-backup.js","variations.js","editor-variations.js","stage-fx.js"));
public static String packageName(String gameId,X509Certificate cert)throws Exception{if(!gameId.matches("[a-zA-Z0-9_-]{1,100}"))throw new IOException("게임 ID 형식");MessageDigest m=MessageDigest.getInstance("SHA-256");m.update(cert.getPublicKey().getEncoded());m.update(gameId.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder("com.eventvn.play.g");for(byte b:m.digest())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
public static void build(File shell,File editor,File data,File output,File work,String pkg,String title,int version,PrivateKey key,X509Certificate cert)throws Exception{build(shell,editor,data,output,work,pkg,title,version,key,cert,null);}
public static void build(File shell,File editor,File data,File output,File work,String pkg,String title,int version,PrivateKey key,X509Certificate cert,File icon)throws Exception{build(shell,editor,data,output,work,pkg,title,version,key,cert,icon,null,null,null);}
/** media: APK path (assets/media/<hash>.<ext>) to file; fonts: font file names the game uses, or null for all;
 * sounds: built-in sound ids (assets/sounds/<id>.ogg) the game uses, or null for all. */
public static void build(File shell,File editor,File data,File output,File work,String pkg,String title,int version,PrivateKey key,X509Certificate cert,File icon,Map<String,File> media,Set<String> fonts,Set<String> sounds)throws Exception{
 if(!pkg.matches("com\\.eventvn\\.play\\.g[a-f0-9]{64}")||title.isEmpty()||title.length()>100||version<1||data.length()>50000000)throw new IOException("APK 내보내기 설정");
 File unsigned=new File(work,"unsigned.apk");Set<String> names=new HashSet<>();boolean iconPlaced=false;
 try(ZipFile base=new ZipFile(shell);ZipFile runtime=new ZipFile(editor);CountStream count=new CountStream(new FileOutputStream(unsigned));ZipOutputStream out=new ZipOutputStream(count)){
  for(Enumeration<? extends ZipEntry> it=base.entries();it.hasMoreElements();){ZipEntry e=it.nextElement();if(e.isDirectory()||e.getName().startsWith("META-INF/"))continue;byte[] bytes=read(base.getInputStream(e),20000000);if(icon!=null&&e.getName().equals(ICON_ART)){bytes=read(new FileInputStream(icon),2000000);iconPlaced=true;}if(e.getName().equals("AndroidManifest.xml"))bytes=manifest(bytes,pkg,title,version);else if(e.getName().equals("resources.arsc"))bytes=resources(bytes,pkg);put(out,count,e.getName(),bytes,e.getName().equals("resources.arsc"));names.add(e.getName());}
  for(Enumeration<? extends ZipEntry> it=runtime.entries();it.hasMoreElements();){ZipEntry e=it.nextElement();String n=e.getName();if(e.isDirectory()||!n.startsWith("assets/"))continue;String rel=n.substring(7),dest=n;
   if(rel.equals("player-index.html"))dest="assets/index.html";else if(!(JS.contains(rel)||rel.startsWith("fonts/")||rel.startsWith("sfx/")||rel.startsWith("sounds/")))continue;
   if(fonts!=null&&rel.startsWith("fonts/")&&rel.endsWith(".woff2")&&!fonts.contains(rel.substring(6)))continue;
   if(rel.startsWith("sounds/")&&(!rel.matches("sounds/[a-z0-9-]{1,40}\\.ogg")||sounds!=null&&!sounds.contains(rel.substring(7,rel.length()-4))))continue;
   put(out,count,dest,read(runtime.getInputStream(e),20000000),false);names.add(dest);
  }
  if(!names.contains("assets/index.html")||!names.contains("classes.dex")||!names.contains("assets/player-bootstrap.js"))throw new IOException("플레이어 구성 누락");
  if(icon!=null&&!iconPlaced)throw new IOException("아이콘 리소스 누락");
  put(out,count,"assets/game.json",read(new FileInputStream(data),50000000),false);
  // Already-compressed pictures and sounds are stored as-is and 4-byte aligned for direct asset reads.
  if(media!=null){long total=0;for(Map.Entry<String,File> m:media.entrySet()){String n=m.getKey();if(!n.matches("assets/media/[a-f0-9]{32}\\.(webp|png|jpg|ogg|mp3|wav|m4a|aac|flac|webm)")||names.contains(n))throw new IOException("그림·소리 파일 형식");byte[] bytes=read(new FileInputStream(m.getValue()),40000000);total+=bytes.length;if(total>300000000L)throw new IOException("그림·소리 크기 제한");put(out,count,n,bytes,!n.endsWith(".wav"));names.add(n);}}
 }
 ApkSigner.SignerConfig signer=new ApkSigner.SignerConfig.Builder("game",key,Collections.singletonList(cert)).build();
 new ApkSigner.Builder(Collections.singletonList(signer)).setInputApk(unsigned).setOutputApk(output).setMinSdkVersion(26).setV1SigningEnabled(false).setV2SigningEnabled(true).setV3SigningEnabled(false).setV4SigningEnabled(false).setOtherSignersSignaturesPreserved(false).build().sign();
 if(!output.isFile()||output.length()<1000)throw new IOException("APK 생성 실패");unsigned.delete();
}
static void put(ZipOutputStream out,CountStream count,String name,byte[] data,boolean stored)throws Exception{ZipEntry e=new ZipEntry(name);e.setTime(1704067200000L);if(stored){e.setMethod(ZipEntry.STORED);e.setSize(data.length);e.setCompressedSize(data.length);CRC32 c=new CRC32();c.update(data);e.setCrc(c.getValue());int pad=(int)((4-(count.size+30+name.getBytes(StandardCharsets.UTF_8).length+6)%4)%4);byte[] extra=new byte[6+pad];extra[0]=0x35;extra[1]=(byte)0xd9;extra[2]=(byte)(pad+2);extra[4]=4;e.setExtra(extra);}out.putNextEntry(e);out.write(data);out.closeEntry();}
static byte[] read(InputStream input,int max)throws IOException{try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("파일 크기 제한");out.write(b,0,n);}return out.toByteArray();}}
static int u16(byte[] b,int o){return (b[o]&255)|((b[o+1]&255)<<8);}static int i32(byte[] b,int o){return u16(b,o)|(u16(b,o+2)<<16);}static void w16(byte[] b,int o,int x){b[o]=(byte)x;b[o+1]=(byte)(x>>8);}static void w32(byte[] b,int o,int x){w16(b,o,x);w16(b,o+2,x>>16);}static void le(ByteArrayOutputStream out,int x){out.write(x);out.write(x>>8);out.write(x>>16);out.write(x>>24);}
static int len8(byte[] b,int[] pos){int a=b[pos[0]++]&255;return (a&128)==0?a:((a&127)<<8)|(b[pos[0]++]&255);}
static List<String> strings(byte[] b,int start)throws IOException{int count=i32(b,start+8),flags=i32(b,start+16),data=start+i32(b,start+20),header=u16(b,start+2);if(count<0||count>10000||i32(b,start+12)!=0)throw new IOException("매니페스트 문자열 형식");List<String> s=new ArrayList<>();for(int i=0;i<count;i++){int p=data+i32(b,start+header+4*i);if((flags&256)!=0){int[] cursor={p};len8(b,cursor);int n=len8(b,cursor);s.add(new String(b,cursor[0],n,StandardCharsets.UTF_8));}else{int n=u16(b,p);p+=2;if((n&32768)!=0){n=((n&32767)<<16)|u16(b,p);p+=2;}s.add(new String(b,p,n*2,StandardCharsets.UTF_16LE));}}return s;}
static byte[] pool(List<String> strings)throws IOException{ByteArrayOutputStream data=new ByteArrayOutputStream();int[] offsets=new int[strings.size()];for(int i=0;i<strings.size();i++){String s=strings.get(i);offsets[i]=data.size();int n=s.length();if(n>=32768){data.write(n>>16);data.write((n>>24)|128);}data.write(n);data.write(n>>8);data.write(s.getBytes(StandardCharsets.UTF_16LE));data.write(0);data.write(0);}while((data.size()&3)!=0)data.write(0);ByteArrayOutputStream out=new ByteArrayOutputStream();le(out,0x001c0001);le(out,28+4*offsets.length+data.size());le(out,offsets.length);le(out,0);le(out,0);le(out,28+4*offsets.length);le(out,0);for(int x:offsets)le(out,x);data.writeTo(out);return out.toByteArray();}
static byte[] manifest(byte[] raw,String pkg,String title,int version)throws Exception{if(u16(raw,0)!=3)throw new IOException("매니페스트 형식");int start=8;while(start<raw.length&&u16(raw,start)!=1)start+=i32(raw,start+4);if(start>=raw.length)throw new IOException("매니페스트 문자열 누락");int oldSize=i32(raw,start+4);List<String>s=strings(raw,start);if(!s.contains(TEMPLATE_PACKAGE)||!s.contains("__GAME_TITLE__")||!s.contains("__GAME_VERSION__"))throw new IOException("플레이어 템플릿 형식");for(int i=0;i<s.size();i++){String v=s.get(i);if(v.equals(TEMPLATE_PACKAGE))s.set(i,pkg);if(v.equals("__GAME_TITLE__"))s.set(i,title);if(v.equals("__GAME_VERSION__"))s.set(i,String.valueOf(version));}byte[] p=pool(s);ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(raw,0,start);out.write(p);out.write(raw,start+oldSize,raw.length-start-oldSize);byte[] b=out.toByteArray();w32(b,4,b.length);boolean found=false;for(int pos=8;pos<b.length;pos+=i32(b,pos+4)){int size=i32(b,pos+4);if(size<8||pos+size>b.length)throw new IOException("매니페스트 청크");if(u16(b,pos)==0x0102){int ext=pos+u16(b,pos+2),attr=ext+u16(b,ext+8),width=u16(b,ext+10),count=u16(b,ext+12);for(int i=0;i<count;i++){int a=attr+i*width;if(s.get(i32(b,a+4)).equals("versionCode")){w32(b,a+16,version);found=true;}}}}if(!found)throw new IOException("버전 코드 누락");return b;}
static byte[] resources(byte[] raw,String pkg)throws Exception{byte[] b=raw.clone();boolean found=false;for(int pos=u16(b,2);pos<b.length;pos+=i32(b,pos+4)){int size=i32(b,pos+4);if(size<8||pos+size>b.length)throw new IOException("리소스 청크");if(u16(b,pos)==0x0200){byte[] name=pkg.getBytes(StandardCharsets.UTF_16LE);if(name.length>=256)throw new IOException("앱 ID 길이");Arrays.fill(b,pos+12,pos+268,(byte)0);System.arraycopy(name,0,b,pos+12,name.length);found=true;}}if(!found)throw new IOException("리소스 패키지 누락");return b;}
static final class CountStream extends FilterOutputStream{long size;CountStream(OutputStream out){super(out);}public void write(int b)throws IOException{out.write(b);size++;}public void write(byte[] b,int o,int n)throws IOException{out.write(b,o,n);size+=n;}}
}
